<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\AuditLog; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\RateLimiter;
class AuthController extends Controller { public function create() { return view('admin.auth.login'); } public function store(Request $request) { $data=$request->validate(['email'=>['required','email'],'password'=>['required','string']]); $key='admin-login:'.$request->ip(); if (RateLimiter::tooManyAttempts($key,5)) return back()->withErrors(['email'=>'Terlalu banyak percobaan. Coba lagi nanti.']); if (!Auth::attempt($data,$request->boolean('remember'))) { RateLimiter::hit($key,60); return back()->withErrors(['email'=>'Kredensial tidak valid.'])->onlyInput('email'); } RateLimiter::clear($key); AuditLog::record('auth.login', $request->user()); $request->session()->regenerate(); return redirect()->intended(route('admin.dashboard')); } public function destroy(Request $request) { Auth::logout(); $request->session()->invalidate(); $request->session()->regenerateToken(); return redirect()->route('admin.login'); } }